1: //! Integration tests for stale reference detection and multi-context refs
2: //!
3: //! These tests verify that the system properly:
4: //! - Detects stale references when elements change or are removed
5: //! - Handles context-prefixed refs correctly
6: //! - Isolates refs between different browser contexts
7: //!
8: //! Run with:
9: //! ```sh
10: //! cargo test --features integration -p viewpoint-mcp --test stale_refs
11: //! ```
12: #![cfg(feature = "integration")]
13: 
14: mod detection;
15: mod edge_cases;
16: mod multi_context;
17: 
18: use viewpoint_mcp::browser::{BrowserConfig, BrowserState};
19: 
20: /// Helper to create a headless browser state
21: pub async fn create_browser() -> BrowserState {
22:     let config = BrowserConfig {
23:         headless: true,
24:         ..Default::default()
25:     };
26:     let mut state = BrowserState::new(config);
27:     state
28:         .initialize()
29:         .await
30:         .expect("Failed to initialize browser");
31:     state
32: }
33: 
34: /// Extract the first ref from a snapshot string
35: /// New format: c{ctx}p{page}f{frame}e{counter} (e.g., c0p0f0e1)
36: pub fn extract_first_ref(snapshot: &str) -> Option<String> {
37:     let re = regex::Regex::new(r"\[ref=(c\d+p\d+f\d+e\d+)\]").unwrap();
38:     re.captures(snapshot)
39:         .map(|c| c.get(1).unwrap().as_str().to_string())
40: }
41: 
42: /// Extract a ref from a snapshot (alias for extract_first_ref with same behavior)
43: /// New format: c{ctx}p{page}f{frame}e{counter} (e.g., c0p0f0e1)
44: pub fn extract_ref(snapshot: &str) -> Option<String> {
45:     // Look for refs in the new format
46:     let re = regex::Regex::new(r"\[ref=(c\d+p\d+f\d+e\d+)\]").unwrap();
47:     re.captures(snapshot)
48:         .map(|c| c.get(1).unwrap().as_str().to_string())
49: }
